{
  "findings": [
    {
      "ref": "[D536]",
      "area": "contact",
      "claim": "A parent reports that voice chat is not available in the PC version of Minecraft.",
      "stance": "risk",
      "quote": "Voice chat is not available in the PC version of the game, but players can use other platforms like Discord to chat while playing."
    },
    {
      "ref": "[D536]",
      "area": "contact",
      "claim": "A parent reports that on console versions, in-game voice chat is available and can be blocked or muted via parental controls.",
      "stance": "mitigation",
      "quote": "those playing on game console platforms, like Xbox and PlayStation, do have access to in-game voice chat. Of course, you can block or limit with whom your kids’ can communicate via parental controls."
    },
    {
      "ref": "[D536]",
      "area": "contact",
      "claim": "A parent reports that players can report suspicious users and servers in-game and on the Minecraft website.",
      "stance": "mitigation",
      "quote": "Additionally, you and your kids are able to report suspicious players and servers in-game and on the Minecraft website for any individuals that may be violating community guidelines."
    },
    {
      "ref": "[D536]",
      "area": "money",
      "claim": "A parent reports that the game offers in-game purchases using Minecoins or platform-specific tokens.",
      "stance": "risk",
      "quote": "Minecoins (*Minecraft*’s in-game currency) can be used to purchase downloadable content in the Minecraft Marketplace. Note that these purchases are completely optional. Minecoins aren’t available for purchase on all platforms, so it may not even be applicable in your home. For example, PlayStation users have access to “Minecraft Tokens” instead."
    },
    {
      "ref": "[D536]",
      "area": "data",
      "claim": "A parent reports that the game collects data for advertising or shares it with third parties, but the policy allows deletion of data.",
      "stance": "neutral",
      "quote": "The ESRB Privacy Certified program is an FTC-sanctioned COPPA Safe Harbor Privacy seal certification program."
    },
    {
      "ref": "[D536]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate is enforced through child accounts requiring parental approval.",
      "stance": "mitigation",
      "quote": "Creating a child account is one of the best ways to make sure your kids have some built in protections to keep their experiences age-appropriate. Microsoft and Minecraft offer child accounts that empower parents to manage and monitor gameplay, multiplayer access, chat settings, and friend requests."
    },
    {
      "ref": "[D536]",
      "area": "content",
      "claim": "A parent reports that the base game contains no violent or gory content, with enemies vanishing when defeated and no glorified violence.",
      "stance": "neutral",
      "quote": "Minecraft does not have violent or gory content in the base game. Enemies and other creatures will simply vanish when defeated, and while players can kill non-threatening animals for food sources, these displays are not glorified."
    },
    {
      "ref": "[D536]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has no known fines, breaches, lawsuits, or regulatory actions mentioned in the text.",
      "stance": "neutral",
      "quote": "Patricia E. Vance is the president of the Entertainment Software Rating Board (ESRB). In her position, she leads the teams responsible for assigning age and content ratings to video games and apps, enforcing marketing guidelines adopted by the video game industry, and operating ESRB Privacy Certified, an FTC-sanctioned COPPA Safe Harbor Privacy seal certification program."
    }
  ]
